import importlib.abc, importlib.machinery, os, sys, types
class Stub(types.ModuleType):
    def __getattr__(self, name):
        if name.startswith("__"):
            raise AttributeError(name)
        return type(name, (), {"__init__": lambda s, *a, **k: None})
class Finder(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, name, path, target=None):
        return importlib.machinery.ModuleSpec(name, self, is_package=True) if name.split(".")[0] == "opentelemetry" else None
    def create_module(self, spec):
        return Stub(spec.name)
    def exec_module(self, m):
        m.__path__ = []
sys.meta_path.insert(0, Finder()); sys.path.insert(0, "otel")
